#!name=贴吧去广告(>=iOS15)
#!author=queitstart pro
#!date=2026-11-21
#!desc=260106;开屏广告;推荐和吧内帖子列表的直播及广告;详情页直播/关联商品/广告;看图模式广告;首页和帖子详情页右下角悬浮广告;部分吧内的置顶/最新中间的广告/head图片广告/head直播
#!arguments=per_filter_video:0
#!arguments-desc=per_filter_video:设置为1则推荐页不展示视频贴
#!format=sgmodule

[Script]
贴吧json = type=http-response,pattern=^https?:\/\/(tiebac|c\.tieba)\.baidu\.com\/(c\/(s\/sync|f\/(ad\/getSplashAd|frs\/(page|threadlist|generalTabList)|pb\/(pic)?page|excellent\/personalized))$|tiebaads\/commonbatch\?),requires-body=1,max-size=0,script-path=https://raw.githubusercontent.com/qs-toolkit/qingqi-mitm-rules/main/scripts/91040c0d5bf906357829d8df344a3bdce00b59e6c24f255e54a2ef7a46d04c69.js,script-update-interval=0
贴吧proto = type=http-response,pattern=^https?:\/\/(tiebac|c\.tieba)\.baidu\.com\/c\/(b\/ad\/adBid|f\/(frs\/(page|threadlist|generalTabList)|ad\/getFeedAd|pb\/page|excellent\/personalized))\?cmd,requires-body=1,binary-body-mode=1,max-size=-1,script-path=https://raw.githubusercontent.com/qs-toolkit/qingqi-mitm-rules/main/scripts/6015d737870b6d89c38a0181479ed715e07d11b5a2c3746f96f95e25835e8610.js,argument=per_filter_video_thread={{{per_filter_video}}}

[Rule]
RULE-SET,https://raw.githubusercontent.com/app2smile/rules/master/rule/tieba-ad.list,REJECT

[MITM]
hostname = %APPEND% tiebac.baidu.com
